// Cross product of vectors (P->Q) and (P->R)
// Positive: CCW turn. Negative: CW turn. Zero: collinear.
function cross(P, Q, R) {
  return (Q.x - P.x) * (R.y - P.y) - (Q.y - P.y) * (R.x - P.x);
}

// Andrew's Monotone Chain - convex hull
function convexHull(points) {
  points.sort((a, b) => a.x !== b.x ? a.x - b.x : a.y - b.y);
  const n = points.length;
  if (n < 3) return points;

  const hull = [];

  // Lower hull: left to right
  for (const p of points) {
    while (hull.length >= 2 && cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.pop();
    }
    hull.push(p);
  }

  // Upper hull: right to left
  const lowerSize = hull.length;
  for (let i = n - 2; i >= 0; i--) {
    while (hull.length > lowerSize && cross(hull[hull.length - 2], hull[hull.length - 1], points[i]) <= 0) {
      hull.pop();
    }
    hull.push(points[i]);
  }

  hull.pop(); // remove duplicate of first point
  return hull;
}

function collinear(P, Q, R) {
  return cross(P, Q, R) === 0;
}
